public class Main {
  record Session(int completed, int target) {
    Session {
      if (target <= 0 || completed < 0 || completed > target)
        throw new IllegalArgumentException("invalid session");
    }
    Session step(String command) {
      if ("done".equals(command) && completed < target)
        return new Session(completed + 1, target);
      return this;
    }
  }
  public static void main(String[] args) {
    Session session = new Session(0, 2);
    for (String command : new String[]{"done", "skip", "done", "done"}) {
      session = session.step(command);
    }
    System.out.println(session.completed() + "/" + session.target());
  }
}
```
